codeExample.code:
public class MethodDemo {

    // Method with no parameters and no return value
    public static void greet() {
        System.out.println("Hello! Welcome to Java.");
    }

    // Method with parameters and a return value
    public static int add(int a, int b) {
        return a + b;
    }

    // Overloaded method: same name, different parameters
    public static double add(double a, double b) {
        return a + b;
    }

    // Method that checks if a number is even
    public static boolean isEven(int number) {
        return number % 2 == 0;
    }

    public static void main(String[] args) {

        // Calling the greet method
        greet();

        // Calling add with integers
        int sum = add(10, 20);
        System.out.println("Sum (int): " + sum);

        // Calling add with doubles (overloaded version)
        double dsum = add(3.5, 2.5);
        System.out.println("Sum (double): " + dsum);

        // Calling isEven and printing result
        boolean result = isEven(7);
        System.out.println("Is 7 even? " + result);
    }
}

