        // Call isPositive with -5 and print the result
    }
}

questions.solution:
public class CheckNumber {

    public static boolean isPositive(int num) {
        return num > 0;
    }

    public static void main(String[] args) {
        boolean result = isPositive(-5);
        System.out.println(result);
    }
}
